using System.IO;
using System.IO.Compression;
using System.Xml;
using System.Xml.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
namespace Ansary;
public sealed record OutlineHeading(int Index,int Level,string Text);
public static class OutlineReader {
 static readonly XNamespace W="http://schemas.openxmlformats.org/wordprocessingml/2006/main";
 static XDocument? Load(ZipArchive zip,string name,long limit){var e=zip.GetEntry(name);if(e==null)return null;if(e.Length>limit)throw new InvalidDataException("ملف المخطط أكبر من حد القراءة الآمنة");using var stream=e.Open();using var r=XmlReader.Create(stream,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=limit});return XDocument.Load(r);}
 public static List<OutlineHeading> Read(string path){if(TextFormats.Markdown(path))return TextFormats.Headings(path).Select(h=>new OutlineHeading(h.Index,h.Level,h.Text)).ToList();if(!Path.GetExtension(path).Equals(".docx",StringComparison.OrdinalIgnoreCase))return new();using var zip=ZipFile.OpenRead(path);var doc=Load(zip,"word/document.xml",32L*1024*1024)??throw new InvalidDataException("ليس ملف DOCX صالحًا");var styleDoc=Load(zip,"word/styles.xml",8L*1024*1024);var styles=(styleDoc?.Descendants(W+"style")??Enumerable.Empty<XElement>()).Where(s=>(string?)s.Attribute(W+"type")=="paragraph").Where(s=>s.Attribute(W+"styleId")!=null).GroupBy(s=>(string)s.Attribute(W+"styleId")!).ToDictionary(g=>g.Key,g=>g.First());string? defaultStyle=styles.FirstOrDefault(kv=>(string?)kv.Value.Attribute(W+"default") is "1" or "true").Key;
  int? Level(XElement p){var pr=p.Element(W+"pPr");var direct=pr?.Element(W+"outlineLvl");if(direct!=null&&int.TryParse((string?)direct.Attribute(W+"val"),out int n))return n>=0&&n<9?n:null;string? id=(string?)pr?.Element(W+"pStyle")?.Attribute(W+"val")??defaultStyle;var seen=new HashSet<string>();while(id!=null&&seen.Add(id)){if(!styles.TryGetValue(id,out var s)){var m=System.Text.RegularExpressions.Regex.Match(id,"^Heading([1-9])$",System.Text.RegularExpressions.RegexOptions.IgnoreCase);return m.Success?int.Parse(m.Groups[1].Value)-1:null;}var outline=s.Element(W+"pPr")?.Element(W+"outlineLvl");if(outline!=null&&int.TryParse((string?)outline.Attribute(W+"val"),out n))return n>=0&&n<9?n:null;id=(string?)s.Element(W+"basedOn")?.Attribute(W+"val");}return null;}
  var headings=new List<OutlineHeading>();int index=0;foreach(var p in doc.Descendants().Where(x=>x.Name.LocalName=="p")){int? level=Level(p);if(level!=null){string text=string.Concat(p.Descendants().Select(x=>x.Name.LocalName switch{"t"=>x.Value,"tab"=>"\t","br"=>"\n",_=>""}));if(!string.IsNullOrWhiteSpace(text))headings.Add(new OutlineHeading(index,level.Value,text));}index++;}return headings;}
 public static void Verify(){string dir=Path.Combine(Path.GetTempPath(),"AnsaryOutline-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string path=Path.Combine(dir,"outline.docx");using(var zip=ZipFile.Open(path,ZipArchiveMode.Create)){void Write(string name,string xml){using var w=new StreamWriter(zip.CreateEntry(name).Open());w.Write(xml);}Write("word/styles.xml","<w:styles xmlns:w='http://schemas.openxmlformats.org/wordprocessingml/2006/main'><w:style w:type='paragraph' w:styleId='Base'><w:pPr><w:outlineLvl w:val='1'/></w:pPr></w:style><w:style w:type='paragraph' w:styleId='Child'><w:basedOn w:val='Base'/></w:style></w:styles>");Write("word/document.xml","<w:document xmlns:w='http://schemas.openxmlformats.org/wordprocessingml/2006/main'><w:body><w:p><w:pPr><w:outlineLvl w:val='0'/></w:pPr><w:r><w:t>بحث عربي سريع</w:t></w:r></w:p><w:p><w:pPr><w:pStyle w:val='Child'/></w:pPr><w:r><w:t>عنوان موروث</w:t></w:r></w:p><w:p><w:pPr><w:pStyle w:val='Child'/><w:outlineLvl w:val='9'/></w:pPr><w:r><w:t>نص عادي</w:t></w:r></w:p></w:body></w:document>");}var h=Read(path);if(h.Count!=2||h[0].Index!=0||h[0].Level!=0||h[1].Index!=1||h[1].Level!=1||!Core.Match(h[0].Text,Core.Terms("سريع بحث")))throw new InvalidDataException("Outline regression");ReaderFeatureLogic.Verify();ReadingData.Verify();LibraryTreeLogic.Verify();TextFormats.Verify();}finally{Directory.Delete(dir,true);}}
}
public sealed partial class LibraryWindow {
 readonly Border outlinePanel=new(){Width=250,Visibility=Visibility.Collapsed,BorderThickness=new Thickness(1),BorderBrush=Brushes.SeaGreen};readonly TextBox outlineQuery=new(){Margin=new Thickness(4)};readonly FastList outlineList=new();readonly TextBlock outlineInfo=new(){Margin=new Thickness(4),TextWrapping=TextWrapping.Wrap};List<OutlineHeading> outlineHeadings=new();readonly Dictionary<DisplayRow,int> outlinePositions=new();DocumentSnapshot? outlineDoc,outlineLoading;int outlineVersion;
 void InitOutline(DockPanel host){var content=new DockPanel();outlinePanel.Child=content;var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);content.Children.Add(top);top.Children.Add(new TextBlock{Text="المخطط التفصيلي — بحث بكلمات دون ترتيب",Margin=new Thickness(4),TextWrapping=TextWrapping.Wrap});top.Children.Add(outlineQuery);top.Children.Add(outlineInfo);content.Children.Add(outlineList);host.Children.Remove(viewer);DockPanel.SetDock(outlinePanel,Dock.Right);host.Children.Add(outlinePanel);host.Children.Add(viewer);LocalButton(viewerBar,"المخطط التفصيلي",async()=>{if(displayed==null){status.Text="افتح ملفًا أولًا";return;}outlinePanel.Visibility=outlinePanel.Visibility==Visibility.Visible?Visibility.Collapsed:Visibility.Visible;if(outlinePanel.Visibility==Visibility.Visible){await LoadOutline(displayed);QueueOutlineSync();}else outlineHistoryPopup.IsOpen=false;});outlineQuery.TextChanged+=(_,_)=>FilterOutline();outlineList.SelectionChanged+=async(_,_)=>{if(syncingOutlineSelection)return;if(outlineList.SelectedItem is DisplayRow row&&outlinePositions.TryGetValue(row,out int index)&&displayed is DocumentSnapshot doc&&activeContext is FileResultContext context&&index<doc.Paragraphs.Length){EnsureFullReaderView(false);var hit=new SearchHit{Path=doc.Path,Index=index,Text=doc.Paragraphs[index],Words=displayedWords,Length=doc.Length,Ticks=doc.Ticks};await Show(hit,context);QueueOutlineSync(index);}};InitReaderFeatures(host,top);InitReadingTools(host);InitSearchAndOpen();InitLibraryManagement();InitFormatControls();}
 void OutlineDocumentChanged(DocumentSnapshot doc){if(ReferenceEquals(outlineDoc,doc)||ReferenceEquals(outlineLoading,doc))return;outlineVersion++;outlineDoc=null;syncedOutlineIndex=-1;outlineHeadings.Clear();outlinePositions.Clear();syncingOutlineSelection=true;try{outlineList.ItemsSource=null;}finally{syncingOutlineSelection=false;}outlineInfo.Text="";if(outlinePanel.Visibility==Visibility.Visible)_=LoadOutline(doc);}
 async Task LoadOutline(DocumentSnapshot doc){if(ReferenceEquals(outlineDoc,doc)){FilterOutline();return;}if(ReferenceEquals(outlineLoading,doc))return;int request=++outlineVersion;outlineLoading=doc;outlineInfo.Text="جار قراءة عناوين المستند…";try{var headings=await Task.Run(()=>{var h=OutlineReader.Read(doc.Path);var info=new FileInfo(doc.Path);if(info.Length!=doc.Length||info.LastWriteTimeUtc.Ticks!=doc.Ticks)throw new IOException("تغيّر الملف؛ أعد فتحه لتحديث المخطط");return h;});if(request!=outlineVersion||!ReferenceEquals(displayed,doc))return;outlineDoc=doc;outlineHeadings=headings;outlineVisibleLevel=8;outlineFoldDirection=-1;FilterOutline();if(Path.GetExtension(doc.Path).Equals(".doc",StringComparison.OrdinalIgnoreCase))outlineInfo.Text="قراءة DOC نصية؛ مخطط DOC وحواشيه غير مدعومين في هذه المعاينة";QueueOutlineSync();}catch(Exception e){if(request==outlineVersion){errors.Add(e.ToString());outlineInfo.Text="تعذر قراءة المخطط: "+e.Message;}}finally{if(request==outlineVersion)outlineLoading=null;}}
 void FilterOutline()=>ApplyOutlineFilter();
}
